def busca_binaria(lista, alvo):
    lo, hi = 0, len(lista) - 1
    while lo <= hi:
        meio = (lo + hi) // 2
        if lista[meio] == alvo:
            return meio
        elif lista[meio] < alvo:
            lo = meio + 1
        else:
            hi = meio - 1
    return -1
```

